// ui/routes/history/branches-and-push.mjs — feature "history". Generated by tools/split-by-feature.mjs v1;
// the body of register() was moved verbatim from ui/server.mjs. Edit it here from now on.
import { appendAuditById } from '../../../src/core/artifacts.mjs';
import { updateBranchRecords } from '../../../src/core/checkout.mjs';
import { getDb } from '../../../src/core/db.mjs';
import { gitState } from '../../../src/core/git-available.mjs';
import { branchTips, listRemoteBranches, pushBranch } from '../../../src/core/git-info.mjs';
import { INTERACTIVE_TIMEOUT_MS, INTERACTIVE_TTL_MS, fetchRemote, isSafeBranchName } from '../../../src/core/git-sync.mjs';
import { actorOf, byActor } from '../../../src/core/identity.mjs';
import { effectiveSyncSettings, projectSyncBlock, sourcePushRemote } from '../../../src/core/project-sync.mjs';
import { isNoProjectWorkDir, projectKey } from '../../../src/core/store.mjs';
import { currentBranch, listLocalBranches } from '../../../src/core/worktree.mjs';
import { badRequest, emitChanged, registeredProjectForDir, resolvePrPipeline, resolveProjectDir } from '../../server.mjs';

export function register(app) {

// ---------------------------------------------------------------------------
// POST /api/push { projectKey | projectDir, id } -> { ok, remote, branch }
// The shipping action of a run on its source branch (branch.sameAsSource): no PR (head == base), so
// push the source — which the run fast-forwarded onto its work — to the remote it syncs from.
// Single-project runs only (a workspace run's state.branch is just its primary member).
app.post('/api/push', async (req, res) => {
  const resolved = await resolvePrPipeline(req.body || {}, res);
  if (!resolved) return;
  const { id, state } = resolved;
  const b = state.branch || {};
  if (b.sameAsSource !== true) return res.status(409).json({ error: 'only a run on its source branch is pushed here. Create a PR instead' });
  if (state.target === 'workspace') return res.status(409).json({ error: 'a workspace run is pushed per project by hand (see its merge-back banner)' });
  // isSafeBranchName: setup already refused any other source; this keeps an edited record out of git's argv.
  if (!state.projectDir || !b.source || !isSafeBranchName(b.source)) return badRequest(res, 'pipeline has no branch info to push');
  if (!(b.mergeBack && b.mergeBack.merged === true)) {
    return res.status(409).json({ error: `the run's work is not on ${b.source} (not merged back). Merge it by hand first` });
  }
  // The run's sync remote — validated like the branch (the record's value ends up in git's argv).
  const remote = sourcePushRemote(b, projectKey(state.projectDir));
  const pushed = await pushBranch(state.projectDir, b.source, remote);
  if (!pushed.ok) return res.status(500).json({ error: `git push failed: ${pushed.stderr}` });
  const by = actorOf(req);
  const runId = state.id || id;
  // Recorded beside the run's branch (as Publish records br.published), so a reload reads "Pushed to <remote>".
  const tips = await branchTips(state.projectDir, b.source, null);
  try {
    updateBranchRecords(runId, ['project'], (br) => {
      br.pushed = { remote, sha: tips?.local || null, at: new Date().toISOString(), by };
    });
  } catch { /* best-effort: the remote-tracking ref still shows the source as pushed */ }
  appendAuditById(runId, `Pushed \`${b.source}\` to \`${remote}\`${byActor(by)}.`, { actor: by });
  emitChanged('pipelines-changed', 'updated');
  res.json({ ok: true, remote, branch: b.source });
});

// ---------------------------------------------------------------------------
// Project registry: GET list / POST add / DELETE remove. Thin delegation to
// src/core/projects.mjs (which owns validation + persistence).
// ---------------------------------------------------------------------------
app.get('/api/branches', async (req, res) => {
  const projectDir = resolveProjectDir(req.query.projectDir);
  if (!projectDir) return badRequest(res, 'projectDir is required');
  if (isNoProjectWorkDir(projectDir)) return res.json({ branches: [], current: null, runs: [] });   // P3: never git in a run's work folder
  try {
    const [branches, current] = await Promise.all([
      listLocalBranches(projectDir),
      currentBranch(projectDir),
    ]);
    // Run branches: this project's pipelines whose feature branch still exists (spec D7).
    // Throw-safe on purpose: test/branches-api.test.mjs calls this route for a temp directory
    // that is not a registered project (and has no temp home) — the DB read must never turn the
    // plain branch list into a 500.
    const have = new Set(branches);
    const runsOut = [];
    try {
      const rows = getDb().prepare(`SELECT id, title, status, updated_at, branch FROM pipelines
        WHERE project_key = ? AND target = 'project' AND archived_at IS NULL AND is_test IS NULL ORDER BY started_at DESC LIMIT 50`).all(projectKey(projectDir));
      for (const r of rows) {
        let b = null; try { b = JSON.parse(r.branch || 'null'); } catch { b = null; }
        if (b && typeof b.feature === 'string' && have.has(b.feature)) runsOut.push({ branch: b.feature, pipelineId: r.id, title: r.title || null, status: r.status, endedAt: r.updated_at || null });
      }
    } catch (err) {
      console.error(`[worca-ui] run branches lookup failed: ${err && err.message ? err.message : err}`);
    }
    const out = { branches, current, runs: runsOut };
    if (req.query.fresh === '1' || req.query.fresh === 'true') {
      // D8: only a REGISTERED project is fetched (a credentialed network call). Any other folder
      // answers from its local refs, exactly as the non-fresh list does.
      // A registry read error degrades to "not registered" (local refs, remote:null), never a 500.
      const reg = await registeredProjectForDir(projectDir).catch((err) => {
        console.error(`[worca-ui] branches: project registry read failed: ${err && err.message ? err.message : err}`);
        return null;
      });
      const key = reg ? reg.key : null;
      const settings = effectiveSyncSettings(key);
      const f = reg
        ? await fetchRemote(projectDir, { remote: settings.remote, maxAgeMs: INTERACTIVE_TTL_MS, timeoutMs: INTERACTIVE_TIMEOUT_MS })
        : { ok: false, kind: 'unregistered', error: 'not a registered project: showing local refs only' };
      if (reg && (f.ok || (f.kind !== 'no-remote' && f.kind !== 'bad-remote'))) {
        const rb = await listRemoteBranches(projectDir, [settings.remote]);
        const base = typeof req.query.base === 'string' && isSafeBranchName(req.query.base) ? req.query.base : current;
        const sync = await projectSyncBlock({ dir: projectDir, projectKey: key, base, mode: 'status', details: true });
        const fetchError = f.ok ? {} : { fetchError: { kind: f.kind, message: f.error } };
        Object.assign(out, {
          remote: { name: settings.remote, branches: rb.ok ? (rb.byRemote[settings.remote] || []) : [] },
          fetchedAt: f.fetchedAt || sync.fetchedAt || null, stale: !f.ok, ...fetchError,
          behind: sync.behind ?? null, sync: { ...sync, stale: !f.ok, ...fetchError },
        });
      } else {
        Object.assign(out, { remote: null, fetchedAt: null, stale: false });
      }
    }
    res.json(out);
  } catch (err) {
    res.status(500).json({ error: err && err.message ? err.message : String(err) });
  }
});

// CONTRACT §0: is git usable here, re-probed at most once a minute (U4: installing git needs no restart).
// A flip broadcasts the `git` frame through onGitChange.
app.get('/api/git', async (_req, res) => {
  const s = await gitState({ maxAgeMs: 60_000 });
  res.json({ available: s.available, version: s.version, reason: s.reason, checkedAt: s.checkedAt });
});
}
